def _one(db, model, tenant_id, **where):
    terms=[model.tenant_id == tenant_id]
    if hasattr(model, "is_deleted"): terms.append(model.is_deleted.is_(False))
    terms.extend(getattr(model,k)==v for k,v in where.items())
    return db.scalars(select(model).where(*terms)).first()
def _put(db, model, tenant_id, key, vals):
    row=_one(db, model, tenant_id, **key)
    if row is None:
        row=model(tenant_id=tenant_id, **key, **vals); db.add(row); db.flush()
    return row

