def validate_internship_operational_coverage(db, tenant_id: int) -> dict:
    from app.models.internship import (InternshipAgreement, InternshipArchive, InternshipBatch,
                                       InternshipBatchPlan, InternshipBatchScopeRule, InternshipFinalScore)
    from app.models.internship_compliance import InternshipComplianceTemplate
    from app.models.internship_enterprise_portal import InternshipRecruitmentCampaign
    current_batch=_one(db,InternshipBatch,tenant_id,batch_no="INT-2024-2026FALL")
    historical_batch=_one(db,InternshipBatch,tenant_id,batch_no="INT-2025-SUMMER-HIST")
    result={"plan":bool(current_batch and _one(db,InternshipBatchPlan,tenant_id,batch_id=current_batch.id)),"scopeRule":bool(current_batch and _one(db,InternshipBatchScopeRule,tenant_id,batch_id=current_batch.id)),"agreement":bool(current_batch and _one(db,InternshipAgreement,tenant_id,batch_id=current_batch.id,status="EFFECTIVE")),"compliance":bool(_one(db,InternshipComplianceTemplate,tenant_id,template_code=f"{MARKER}-COMPLIANCE")),"recruitment":bool(_one(db,InternshipRecruitmentCampaign,tenant_id,campaign_code=f"{MARKER}-ROUND2",status="OPEN")),"historicalArchive":bool(historical_batch and _one(db,InternshipArchive,tenant_id,batch_id=historical_batch.id,status="ARCHIVED")),"historicalFinalScore":bool(historical_batch and _one(db,InternshipFinalScore,tenant_id,batch_id=historical_batch.id,status="ARCHIVED"))}
    result["passed"]=all(result.values())
    if not result["passed"]: raise RuntimeError(f"internship coverage invalid: {result}")
    return result
